import sys,re; import os; sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from httpkit import *
b=B(); b.get('/login'); b.post('/login',{'username':'admin_test','password':'Sup3rSecret99'})
b.get('/app/teams'); check('teams page',b.r.status_code==200 and 'Rescue Teams' in b.last,b.r.status_code)
b.post('/app/teams',{'action':'create','_modal':'createTeam','teamName':'Alpha Rescue','teamType':'FIRE_RESCUE','leaderName':'Ravi','contactNumber':'9876501234','memberCount':'8','baseLocation':'Malappuram','skills':'rope rescue, first aid','equipment':'boats'})
check('register team',b.alert() and b.alert()[0]=='success',b.alert())
b.get('/app/teams'); tid=re.search(r'/app/teams\?id=(\d+)',b.last).group(1)
b.get('/app/teams?id='+tid); check('team detail page',b.r.status_code==200 and 'Alpha Rescue' in b.last and 'Members (' in b.last,b.r.status_code)
b.post('/app/teams?id='+tid,{'action':'addMember','id':tid,'memberName':'Sita','role':'Medic','contactNumber':'9876500000','specialSkills':'CPR'})
check('add member',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/teams?id='+tid,{'action':'addSkill','id':tid,'skillName':'Diving','description':'swift water'}); check('add skill',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/teams?id='+tid,{'action':'addEquipment','id':tid,'equipmentName':'Life jackets','quantity':'20','description':''}); check('add equipment',b.alert() and b.alert()[0]=='success',b.alert())
mid=re.search(r'data-member-id="(\d+)"',b.last).group(1)
b.post('/app/teams?id='+tid,{'action':'updateMember','id':tid,'memberId':mid,'memberName':'Sita R','role':'Senior Medic','contactNumber':'9876500000','specialSkills':'CPR','availability':'AVAILABLE'}); check('update member',b.alert() and b.alert()[0]=='success',b.alert())
check('member rename shown','Sita R' in b.last)
b.post('/app/teams?id='+tid,{'action':'availability','id':tid,'availability':'AVAILABLE'}); check('availability',b.alert() and b.alert()[0]=='success',b.alert())
# requests
b.get('/app/disasters'); did=re.search(r'data-id="(\d+)" data-title="Kerala Flood Test"',b.last).group(1)
b.get('/app/requests'); check('requests page',b.r.status_code==200 and 'Rescue Requests' in b.last)
b.post('/app/requests',{'action':'create','_modal':'createRequest','requesterName':'Meera','contactNumber':'9000000001','disasterId':did,'location':'Nilambur','people':'5','children':'2','elderly':'1','lifeThreatening':'on','trapped':'on','assistance':'boat needed'})
check('create request (life-threatening)',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/requests',{'action':'create','_modal':'createRequest','requesterName':'Low One','contactNumber':'9000000002','disasterId':did,'location':'Town','people':'1','children':'0','elderly':'0','assistance':'food'})
b.get('/app/requests'); rows=re.findall(r'<tr data-row>(.*?)</tr>',b.last,re.S)
txt=[re.sub(r'<[^>]+>|\s+',' ',x) for x in rows]
hi=[t for t in txt if 'Meera' in t][0]; lo=[t for t in txt if 'Low One' in t][0]
print('   Meera row:',hi.strip()[:110]); print('   Low  row:',lo.strip()[:110])
check('priority logic: life-threatening+trapped -> Critical','Critical' in hi,hi)
check('priority logic: single person food -> Low/Medium','Low' in lo or 'Medium' in lo,lo)
rid=re.search(r'/app/requests\?id=(\d+)',[r for r in rows if 'Meera' in r][0]).group(1)
b.get('/app/requests?id='+rid); check('request detail + priority explanation','How the priority was calculated' in b.last and r'Start review' in b.last)
exp=re.search(r'font-family:inherit">(.*?)</pre>',b.last,re.S).group(1).strip(); print('   explanation:',exp[:160].replace('\n',' | '))
b.post('/app/requests?id='+rid,{'action':'startReview','id':rid}); check('start review -> detail shows assign',b.alert() and b.alert()[0]=='success' and 'Assign a team' in b.last,b.alert())
b.post('/app/requests?id='+rid,{'action':'assign','id':rid,'teamId':tid}); check('assign team',b.alert() and b.alert()[0]=='success',b.alert())
aid=re.search(r'name="assignmentId" value="(\d+)"',b.last).group(1)
b.post('/app/requests?id='+rid,{'action':'progress','assignmentId':aid,'target':'EN_ROUTE','notes':''}); check('en route',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/requests?id='+rid,{'action':'progress','assignmentId':aid,'target':'ON_SITE','notes':''}); check('on site',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/requests?id='+rid,{'action':'complete','assignmentId':aid}); check('complete -> Rescued',b.alert() and b.alert()[0]=='success' and 'Rescued' in b.last,b.alert())
# citizen form
b.get('/app/report-emergency'); check('admin blocked from citizen form (403)',b.r.status_code==403)
sys.exit(1 if summary() else 0)
